<template>
	<div class="pb-widget-settings pb-widget-settings--basic-gallery">
		<div class="pb-tab-nav">
			<button type="button" class="pb-tab-btn pb-tab-btn-icon" :class="{active:editor.settingsTab==='content'}" @click="editor.settingsTab='content'"><i class="fas fa-edit"></i><span>Content</span></button>
			<button type="button" class="pb-tab-btn pb-tab-btn-icon" :class="{active:editor.settingsTab==='style'}" @click="editor.settingsTab='style'"><i class="fas fa-adjust"></i><span>Style</span></button>
			<button type="button" class="pb-tab-btn pb-tab-btn-icon" :class="{active:editor.settingsTab==='advanced'}" @click="editor.settingsTab='advanced'"><i class="fas fa-gear"></i><span>Advanced</span></button>
		</div>
		<div v-if="editor.settingsTab==='content'" class="pb-tab-content"><details class="pb-collapsible" open><summary>Basic Gallery</summary><div class="pb-collapsible-body">
			<div class="pb-form-group pb-basic-gallery-images-control"><div class="pb-label-row"><label class="pb-form-label mb-0">Images</label></div><div class="pb-basic-gallery-picker" :class="{'is-empty':!node.settings.images.length}">
				<div class="pb-basic-gallery-picker__head"><span>{{ node.settings.images.length ? node.settings.images.length+' Images Selected' : 'No Images Selected' }}</span><button type="button" class="pb-btn icon-sm" title="Add Images" aria-label="Add images" @click="editor.chooseMediaGallery(node.settings, 'images')"><i class="fas fa-plus"></i></button></div>
				<div v-for="(image,index) in node.settings.images" :key="image.id" class="pb-basic-gallery-picker__item"><img :src="image.url" :alt="image.alt || ''"><div class="pb-basic-gallery-picker__meta"><input class="pb-input" v-model="image.alt" placeholder="Alt text"><input class="pb-input" v-model="image.caption" placeholder="Attachment caption"></div><div class="pb-basic-gallery-picker__actions"><button type="button" :disabled="index===0" title="Move Up" aria-label="Move image up" @click="editor.moveMediaGalleryItem(node.settings, 'images', image.id, -1)"><i class="fas fa-chevron-up"></i></button><button type="button" :disabled="index===node.settings.images.length-1" title="Move Down" aria-label="Move image down" @click="editor.moveMediaGalleryItem(node.settings, 'images', image.id, 1)"><i class="fas fa-chevron-down"></i></button><button type="button" title="Remove Image" aria-label="Remove image" @click="editor.removeMediaGalleryItem(node.settings, 'images', image.id)"><i class="fas fa-trash-alt"></i></button></div></div>
				<button type="button" class="pb-basic-gallery-picker__add" @click="editor.chooseMediaGallery(node.settings, 'images')"><i class="fas fa-plus-circle"></i><span>Add Images</span></button>
			</div></div>
			<div class="pb-form-group"><label class="pb-form-label">Image Resolution</label><select class="pb-select" v-model="node.settings.imageResolution"><option v-for="option in resolutionOptions" :key="option.value" :value="option.value">{{ option.label }}</option></select></div>
			<div v-if="node.settings.imageResolution === 'custom'" class="pb-carousel-custom-resolution"><div class="pb-form-note">Crop each image to the selected dimensions.</div><label><span>Width</span><input class="pb-input" type="number" min="1" max="4096" v-model.number="node.settings.customImageWidth" :aria-invalid="customResolutionError ? 'true' : 'false'" aria-describedby="basic-gallery-custom-resolution-error"></label><label><span>Height</span><input class="pb-input" type="number" min="1" max="4096" v-model.number="node.settings.customImageHeight" :aria-invalid="customResolutionError ? 'true' : 'false'" aria-describedby="basic-gallery-custom-resolution-error"></label><p v-if="customResolutionError" id="basic-gallery-custom-resolution-error" class="pb-form-error" role="alert">{{ customResolutionError }}</p></div>
			<responsive-select label="Columns" base="columns" control-id="basic-gallery-columns" :node="node" :editor="editor" :options="columnOptions" />
			<div class="pb-form-group"><label class="pb-form-label">Caption</label><select class="pb-select" v-model="node.settings.captionType"><option value="none">None</option><option value="caption">Attachment Caption</option></select></div>
			<div class="pb-form-group"><label class="pb-form-label">Link</label><select class="pb-select" v-model="node.settings.linkType"><option value="none">None</option><option value="media">Media File</option><option value="attachment">Attachment Page</option></select></div>
			<div v-if="node.settings.linkType === 'media'" class="pb-form-group"><label class="pb-form-label">Lightbox</label><select class="pb-select" v-model="node.settings.lightbox"><option value="default">Default</option><option value="yes">Yes</option><option value="no">No</option></select></div>
			<div class="pb-form-group"><label class="pb-form-label">Order By</label><select class="pb-select" v-model="node.settings.orderBy"><option value="default">Default</option><option value="random">Random</option></select></div>
		</div></details></div>
		<div v-if="editor.settingsTab==='style'" class="pb-tab-content">
			<details class="pb-collapsible" open><summary>Images</summary><div class="pb-collapsible-body">
				<div class="pb-form-group"><label class="pb-form-label">Gap</label><select class="pb-select" v-model="node.settings.gapMode"><option value="default">Default</option><option value="no_gap">No Gap</option><option value="narrow">Narrow</option><option value="extended">Extended</option><option value="wide">Wide</option><option value="custom">Custom</option></select></div>
				<size-control v-if="node.settings.gapMode === 'custom'" label="Custom Gap" base="gap" control-id="basic-gallery-gap" fallback="10px" :node="node" :editor="editor" />
				<div class="pb-form-group"><label class="pb-form-label">Border Type</label><select class="pb-select" v-model="node.settings.imageBorderType"><option v-for="type in borderTypes" :key="type.value" :value="type.value">{{ type.label }}</option></select></div>
				<sides-control v-if="!['default','none'].includes(node.settings.imageBorderType)" label="Border Width" base="imageBorderWidth" control-id="basic-gallery-border-width" :node="node" :editor="editor" :responsive="false" />
				<color-control v-if="!['default','none'].includes(node.settings.imageBorderType)" label="Border Color" setting-key="imageBorderColor" :node="node" />
				<sides-control label="Border Radius" base="imageBorderRadius" control-id="basic-gallery-border-radius" :node="node" :editor="editor" :responsive="true" />
			</div></details>
			<details v-if="node.settings.captionType !== 'none'" class="pb-collapsible"><summary>Caption</summary><div class="pb-collapsible-body"><responsive-choice label="Alignment" base="captionAlignment" control-id="basic-gallery-caption-alignment" :node="node" :editor="editor" :options="captionAlignOptions" /><color-control label="Text Color" setting-key="captionColor" :node="node" /><div class="pb-subsection-title">Typography</div><component :is="editor.typographyControl" prefix="caption" :settings="node.settings" :responsive-device="editor.responsiveDevice" :font-families="editor.fontFamilies" :reset-defaults="{FontSize:'16px',FontWeight:'400',LineHeight:'1.5em'}" @responsive-device="editor.setResponsiveDevice" /><component :is="editor.textShadowControl" aria-label="Text Shadow" :model-value="node.settings.captionTextShadow" control-id="basic-gallery-caption-shadow" :open="activeTextEffect==='caption-shadow'" @request-open="activeTextEffect=$event" @update:modelValue="node.settings.captionTextShadow=$event" /><size-control label="Spacing" base="captionSpacing" control-id="basic-gallery-caption-spacing" fallback="8px" :node="node" :editor="editor" /></div></details>
		</div>
		<div v-if="editor.settingsTab==='advanced'" class="pb-tab-content"><component :is="editor.widgetAdvancedControls" :node="node" :responsive-device="editor.responsiveDevice" :show-display-conditions="false" :show-cache-settings="false" :elementor-choices="true" @responsive-device="editor.setResponsiveDevice" @choose-media="editor.chooseMedia(node.settings,$event)" @clear-media="editor.clearMedia(node.settings,$event)" @unavailable-ai="editor.showUnsupportedControlNotice('Animate With AI', 'AI service is not connected to this page builder.')" /></div>
	</div>
</template>
<script>
const ResponsiveMenu={props:['editor','id'],template:`<div class="pb-control-device-wrap"><button type="button" class="pb-control-device-btn" @click.stop="editor.openControlResponsiveMenu(id)" :title="'Responsive: '+editor.responsiveDeviceLabel()"><i :class="editor.responsiveDeviceIcon()"></i></button><div v-if="editor.isControlResponsiveMenuOpen(id)" class="pb-control-device-menu"><button v-for="device in editor.responsiveDevices" :key="id+'-'+device.value" type="button" class="pb-control-device-item" :class="{active:editor.responsiveDevice===device.value}" @click.stop="editor.applyResponsiveDevice(id,device.value)"><i :class="device.icon"></i><span>{{ editor.deviceOptionLabel(device) }}</span></button></div></div>`};
const ResponsiveSelect={components:{ResponsiveMenu},props:['label','base','controlId','node','editor','options'],template:`<div class="pb-form-group"><div class="pb-label-row pb-label-row-device"><label class="pb-form-label mb-0">{{label}}</label><responsive-menu :editor="editor" :id="controlId"/></div><select class="pb-select" :value="node.settings[editor.activeResponsiveKey(base)]||'default'" @change="editor.setResponsiveSetting(node.settings,base,$event.target.value)"><option v-for="option in options" :key="base+'-'+option.value" :value="option.value">{{option.label}}</option></select></div>`};
const ToggleControl={props:['label','settingKey','node'],template:`<div class="pb-form-group pb-toggle-label-row"><label class="pb-form-label mb-0">{{label}}</label><div class="pb-toggle-switch-wrap"><div class="pb-toggle-wrap"><input :id="'image-carousel-'+settingKey" type="checkbox" class="pb-toggle" v-model="node.settings[settingKey]"><label :for="'image-carousel-'+settingKey"></label></div><span class="pb-toggle-state">{{node.settings[settingKey]?'Yes':'No'}}</span></div></div>`};
const ColorControl={props:['label','settingKey','node'],template:`<div class="pb-form-group"><label class="pb-form-label">{{label}}</label><input class="pb-input coloris pb-coloris-input" v-model="node.settings[settingKey]"></div>`};
const SizeControl={components:{ResponsiveMenu},props:['label','base','controlId','fallback','node','editor'],template:`<div class="pb-form-group"><div class="pb-label-row pb-label-row-device"><label class="pb-form-label mb-0">{{label}}</label><responsive-menu :editor="editor" :id="controlId"/></div><div class="pb-range-value-row"><input class="pb-range" type="range" min="0" :max="editor.sizeControlMax(node,base,fallback)" :step="editor.sizeControlStep(node,base,fallback)" :value="editor.sizeControlDisplayValue(node,base,fallback)" @input="editor.onSizeControlInput(node,base,$event,{fallback})"><div class="pb-value-with-unit"><input class="pb-input pb-input-compact" type="number" :value="editor.sizeControlDisplayValue(node,base,fallback)" @input="editor.onSizeControlInput(node,base,$event,{fallback})"><select class="pb-mini-unit" :value="editor.sizeControlUnit(node,base,fallback)" @change="editor.setSizeControlUnit(node,base,$event.target.value,{fallback})"><option v-for="unit in editor.sizeControlUnits" :key="unit" :value="unit">{{unit}}</option></select></div></div></div>`};
const ResponsiveChoice={components:{ResponsiveMenu},props:['label','base','controlId','node','editor','options'],template:`<div class="pb-form-group"><div class="pb-label-row pb-label-row-device"><label class="pb-form-label mb-0">{{label}}</label><responsive-menu :editor="editor" :id="controlId"/></div><div class="pb-btn-group pb-image-box-segmented"><button v-for="option in options" :key="base+'-'+option.value" type="button" class="pb-seg-btn" :class="{active:node.settings[editor.activeResponsiveKey(base)]===option.value}" :title="option.label" @click="editor.setResponsiveSetting(node.settings,base,option.value)"><i :class="option.icon"></i></button></div></div>`};
const SidesControl={components:{ResponsiveMenu},props:{label:String,base:String,controlId:String,node:Object,editor:Object,responsive:{type:Boolean,default:true}},data(){return{linked:true,sides:['Top','Right','Bottom','Left'],units:['px','%','em','rem']};},methods:{key(side){return this.base+side;},unit(){return this.editor.sizeControlUnit(this.node,this.key('Top'),'0px',{allowedUnits:this.units});},value(side){return this.editor.sizeControlDisplayValue(this.node,this.key(side),'0px',{allowedUnits:this.units});},setSide(side,event){const number=Number(event.target.value);const token=`${Number.isFinite(number)?Math.max(0,number):0}${this.unit()}`;(this.linked?this.sides:[side]).forEach(target=>this.responsive?this.editor.setResponsiveSetting(this.node.settings,this.key(target),token):this.node.settings[this.key(target)]=token);},setUnit(event){const next=this.units.includes(event.target.value)?event.target.value:'px';this.sides.forEach(side=>{const token=`${this.value(side)}${next}`;this.responsive?this.editor.setResponsiveSetting(this.node.settings,this.key(side),token):this.node.settings[this.key(side)]=token;});}},template:`<div class="pb-form-group pb-icon-box-sides-control"><div class="pb-label-row pb-label-row-device"><label class="pb-form-label mb-0">{{label}}</label><div class="pb-label-tools"><responsive-menu v-if="responsive" :editor="editor" :id="controlId"/><select class="pb-mini-unit" :value="unit()" @change="setUnit($event)"><option v-for="option in units" :key="base+'-'+option" :value="option">{{option}}</option></select></div></div><div class="pb-four-sides pb-four-sides-with-link"><label v-for="side in sides" :key="side" class="pb-side-input"><input class="pb-input" type="number" min="0" :value="value(side)" @input="setSide(side,$event)"><span>{{side}}</span></label><div class="pb-side-link-cell"><button type="button" class="pb-link-btn" :class="{active:linked}" @click="linked=!linked"><i :class="linked?'fas fa-link':'fas fa-unlink'"></i></button></div></div></div>`};export default{name:'BasicGalleryWidgetSettings',props:{node:{type:Object,required:true},editor:{type:Object,required:true}},components:{ResponsiveMenu,ResponsiveSelect,ToggleControl,ColorControl,SizeControl,ResponsiveChoice,SidesControl},data(){return{activeTextEffect:''};},computed:{resolutionOptions(){return[{value:'thumbnail',label:'Thumbnail - 150 x 150'},{value:'medium',label:'Medium - 300 x 300'},{value:'medium_large',label:'Medium Large - 768 x 0'},{value:'large',label:'Large - 1024 x 1024'},{value:'1536x1536',label:'1536 x 1536'},{value:'2048x2048',label:'2048 x 2048'},{value:'full',label:'Full'},{value:'custom',label:'Custom'}];},customResolutionError(){const dimensions=[this.node.settings.customImageWidth,this.node.settings.customImageHeight];return dimensions.every(value=>{const dimension=Number(value);return Number.isInteger(dimension)&&dimension>=1&&dimension<=4096;})?'':'Use a whole number from 1 to 4096 px for both Width and Height.';},columnOptions(){return Array.from({length:10},(_,index)=>({value:String(index+1),label:String(index+1)}));},verticalAlignOptions(){return[{value:'start',label:'Start',icon:'fas fa-align-left'},{value:'center',label:'Center',icon:'fas fa-align-center'},{value:'end',label:'End',icon:'fas fa-align-right'}];},captionAlignOptions(){return[{value:'left',label:'Left',icon:'fas fa-align-left'},{value:'center',label:'Center',icon:'fas fa-align-center'},{value:'right',label:'Right',icon:'fas fa-align-right'},{value:'justify',label:'Justified',icon:'fas fa-align-justify'}];},borderTypes(){return['default','none','solid','double','dotted','dashed','groove'].map(value=>({value,label:value.charAt(0).toUpperCase()+value.slice(1)}));}}};
</script>

<style scoped>
.pb-carousel-gallery{border:1px solid #dce3ef;border-radius:6px;overflow:hidden;background:#fff}.pb-carousel-gallery__head{display:flex;align-items:center;justify-content:space-between;padding:8px 10px;background:#f7f9fc;font-size:12px;font-weight:600}.pb-carousel-gallery__item{display:grid;grid-template-columns:54px minmax(0,1fr) 28px;gap:8px;padding:8px;border-top:1px solid #e7ebf2}.pb-carousel-gallery__item img{width:54px;height:54px;object-fit:cover;border-radius:4px;background:#edf1f7}.pb-carousel-gallery__meta{display:grid;gap:5px}.pb-carousel-gallery__actions{display:flex;flex-direction:column;gap:3px}.pb-carousel-gallery__actions button{border:0;background:transparent;color:#667085;padding:3px}.pb-carousel-gallery__actions button:last-child{color:#b42318}.pb-carousel-gallery__add{width:100%;display:flex;gap:6px;align-items:center;justify-content:center;border:0;border-top:1px solid #e7ebf2;background:#fff;padding:10px;color:#4f46e5}.pb-carousel-custom-resolution{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:14px}.pb-carousel-custom-resolution .pb-form-note,.pb-carousel-custom-resolution .pb-form-error{grid-column:1/-1}.pb-carousel-custom-resolution label span{display:block;font-size:11px;margin-bottom:4px}.pb-carousel-custom-resolution .pb-form-error{margin:0;color:#b42318;font-size:12px;line-height:1.4}
.pb-basic-gallery-images-control>.pb-label-row{display:flex;align-items:center;justify-content:space-between;margin-bottom:5px}.pb-basic-gallery-picker{overflow:hidden;border:1px solid #dce3ef;border-radius:6px;background:#fff}.pb-basic-gallery-picker__head{display:flex;align-items:center;justify-content:space-between;min-height:38px;padding:7px 9px;background:#f7f9fc;font-size:12px;font-weight:600}.pb-basic-gallery-picker__item{display:grid;grid-template-columns:52px minmax(0,1fr) 28px;gap:8px;padding:8px;border-top:1px solid #e7ebf2}.pb-basic-gallery-picker__item img{width:52px;height:52px;object-fit:cover;border-radius:4px;background:#edf1f7}.pb-basic-gallery-picker__meta{display:grid;gap:5px;min-width:0}.pb-basic-gallery-picker__actions{display:flex;flex-direction:column;gap:2px;opacity:.42;transition:opacity .16s ease}.pb-basic-gallery-picker__item:hover .pb-basic-gallery-picker__actions,.pb-basic-gallery-picker__item:focus-within .pb-basic-gallery-picker__actions{opacity:1}.pb-basic-gallery-picker__actions button{min-width:26px;min-height:26px;padding:3px;border:0;background:transparent;color:#667085}.pb-basic-gallery-picker__actions button:last-child{color:#b42318}.pb-basic-gallery-picker__actions button:disabled{opacity:.35}.pb-basic-gallery-picker__add{display:flex;align-items:center;justify-content:center;gap:6px;width:100%;padding:10px;border:0;border-top:1px solid #e7ebf2;background:#fff;color:#4f46e5}
</style>
